<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) · Piet Mondrian</title>
<meta name="description" content="Piet Mondrian, Composition with Red, Blue and Yellow, 1930. De Stijl, Neoplasticism, and why the painting matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Jost:wght@300;400;600;800&display=swap" rel="stylesheet">
<style>
:root{--red:#d6201a;--blue:#12399b;--yellow:#fbd10a;--black:#111;--white:#f6f4ee;--line:clamp(6px,1vw,12px)}
*{box-sizing:border-box;margin:0}
body{background:var(--white);color:var(--black);font-family:"Jost","Helvetica Neue",Arial,sans-serif;font-size:clamp(1rem,1.2vw + .6rem,1.25rem);line-height:1.5}
.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:var(--line);background:var(--black);border:var(--line) solid var(--black);min-height:100vh}
.grid>*{background:var(--white);padding:clamp(1rem,3vw,2.5rem)}
.hero{grid-column:1/-1;display:grid;grid-template-columns:repeat(12,1fr);gap:var(--line);padding:0;background:var(--black)}
.hero>*{background:var(--white)}
.title{grid-column:1/5;padding:clamp(1rem,3vw,2.5rem);display:flex;flex-direction:column;justify-content:space-between;gap:2rem}
.kicker{font-weight:600;letter-spacing:.2em;text-transform:uppercase;font-size:.8rem}
h1{font-weight:800;font-size:clamp(2rem,5vw,4.2rem);line-height:.98;letter-spacing:-.02em}
h1 span{display:block;font-weight:300}
.art{grid-column:5/-1;padding:0;display:block}
.art svg{display:block;width:100%;height:auto;aspect-ratio:1/1;max-height:90vh}
.art figcaption{padding:.6rem 1rem;font-size:.8rem}
.facts{grid-column:1/5;background:var(--yellow)}
.facts dl{display:grid;gap:.9rem}
dt{font-size:.75rem;letter-spacing:.18em;text-transform:uppercase;font-weight:600}
dd{font-weight:800;font-size:1.5rem;line-height:1.1}
.movement{grid-column:5/13}
.rules{grid-column:1/8;background:var(--blue);color:#fff}
.palette{grid-column:8/13;background:var(--red);color:#fff}
.matters{grid-column:1/10}
.more{grid-column:10/13;background:var(--black);color:#fff;display:flex;flex-direction:column;justify-content:space-between;gap:1.5rem}
.sw{display:flex;gap:.5rem;margin-top:1rem}
.sw i{width:2.2rem;height:2.2rem;border:2px solid #fff;display:block}
h2{font-weight:800;font-size:clamp(1.4rem,2.4vw,2.1rem);line-height:1.05;margin-bottom:.8rem}
p+p{margin-top:.8rem}
.rules li{margin-left:1.1rem}
.cta{display:inline-block;background:var(--yellow);color:var(--black);font-weight:800;text-decoration:none;padding:.9rem 1.2rem;border:var(--line) solid var(--yellow);transition:background .2s,color .2s}
.cta:hover,.cta:focus-visible{background:var(--black);color:var(--yellow);outline:3px solid var(--yellow);outline-offset:2px}
footer{grid-column:1/-1;font-size:.8rem;padding-block:.8rem}
@media(max-width:800px){
 .title,.art,.facts,.movement,.rules,.palette,.matters,.more{grid-column:1/-1}
}
@media(prefers-reduced-motion:no-preference){
 .blk{transform-origin:center;animation:in .9s cubic-bezier(.2,.8,.2,1) both}
 .b2{animation-delay:.15s}.b3{animation-delay:.3s}
 @keyframes in{from{opacity:0;transform:scale(.6)}}
}
</style>
</head>
